/**
 * Golden contract for the SM-18 format-write port follow-up on
 * `info/contents.dat` (sm18-re gitlab #48).
 *
 * The fixture `test/fixtures/sm18-port-format-write-contents.json` is a
 * byte-for-byte mirror of
 * `sm18-re:tests/fixtures/port-format-write-contents.json`, generated by
 * `sm18-re:scripts/export-port-format-write-contents-fixture.py` on the
 * sample collection "ABC of SuperMemo 18". The lane re-copies the mirror on
 * every fixture change so sm18-re's gate catches drift on either side.
 *
 * This file is brief-writer owned. The lane implements the new export in
 * `src/sm18-format-write.ts`:
 *
 *   writeContents(header: Uint8Array, records: ContentsRecord[]): Uint8Array
 *
 * `ContentsRecord` is already declared on the read side
 * (`src/sm18-format-read.ts`) and carries the ten `unknown_0x%02x` fields
 * the Python reference exposes. Together those ten offsets cover every byte
 * of the 37-byte record, so a repack from `ContentsRecord[]` reproduces the
 * stored bytes byte-for-byte; no `_raw` carrier is needed. The TS writer
 * must reject a non-empty header the same way `smfmt.contents.write` does,
 * and must preserve the deliberately unaligned u32 offsets (every member
 * sits at `≡ 1 (mod 4)`) by writing through a `DataView` rather than a
 * `Uint32Array`.
 *
 * Each file in the fixture carries `expected_bytes_b64` and a `records`
 * array of ten-field records. The harness feeds the records into
 * `writeContents` and asserts the output byte sequence equals
 * `expected_bytes_b64`.
 */

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";

import type { ContentsRecord } from "../src/sm18-format-read";

const FIXTURE_PATH = join(
  __dirname,
  "fixtures",
  "sm18-port-format-write-contents.json",
);
const MODULE_SPEC = ["..", "src", "sm18-format-write.ts"].join("/");

interface FixtureFile {
  path: string;
  byte_length: number;
  header_b64: string;
  record_count: number;
  records: ContentsRecord[];
  expected_bytes_b64: string;
}

interface Fixture {
  schema: number;
  collection: string;
  scope: string[];
  files: FixtureFile[];
}

interface PortModule {
  writeContents: (
    header: Uint8Array,
    records: ContentsRecord[],
  ) => Uint8Array;
}

async function loadPort(): Promise<PortModule | null> {
  try {
    const mod = await import(MODULE_SPEC);
    if (typeof mod?.writeContents !== "function") {
      return null;
    }
    return mod as PortModule;
  } catch {
    return null;
  }
}

function decodeBase64(encoded: string): Uint8Array {
  return new Uint8Array(Buffer.from(encoded, "base64"));
}

function bytesEqual(a: Uint8Array, b: Uint8Array): boolean {
  if (a.byteLength !== b.byteLength) return false;
  for (let i = 0; i < a.byteLength; i += 1) {
    if (a[i] !== b[i]) return false;
  }
  return true;
}

const fixture: Fixture = JSON.parse(readFileSync(FIXTURE_PATH, "utf8"));

test("fixture declares the contents scope and non-empty file set", () => {
  assert.equal(fixture.schema, 1);
  assert.deepEqual(fixture.scope, ["contents"]);
  assert.ok(fixture.files.length > 0, "at least one file is pinned");
  for (const file of fixture.files) {
    assert.equal(
      file.records.length,
      file.record_count,
      `${file.path} record_count matches records length`,
    );
    assert.equal(
      file.byte_length,
      file.record_count * 37,
      `${file.path} byte_length is 37 bytes per record`,
    );
    assert.equal(file.header_b64, "", `${file.path} has empty header`);
  }
});

test("src/sm18-format-write.ts exports writeContents", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("src/sm18-format-write.ts does not yet export writeContents");
    return;
  }
  assert.equal(typeof port.writeContents, "function");
});

for (const file of fixture.files) {
  test(`format-write contents: ${file.path} rebuilds ${file.byte_length} bytes`, async (t) => {
    const port = await loadPort();
    if (port === null) {
      t.skip("src/sm18-format-write.ts does not yet export writeContents");
      return;
    }
    const header = decodeBase64(file.header_b64);
    const expected = decodeBase64(file.expected_bytes_b64);
    assert.equal(
      expected.byteLength,
      file.byte_length,
      `expected byte count for ${file.path}`,
    );
    const produced = port.writeContents(header, file.records);
    assert.ok(
      bytesEqual(produced, expected),
      `${file.path} must round-trip byte for byte ` +
        `(got ${produced.byteLength} bytes, expected ${expected.byteLength})`,
    );
  });
}

test("writeContents rejects a non-empty header", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("src/sm18-format-write.ts does not yet export writeContents");
    return;
  }
  assert.throws(() => port.writeContents(new Uint8Array([0x00]), []));
});
